export class Version {
  major: number;
  minor: number;
  micro: number;
  dev: number;

  constructor(major = 0, minor = 0, micro = 0, dev = 0) {
    this.major = major;
    this.minor = minor;
    this.micro = micro;
    this.dev = dev;
  }

  toJSON() {
    return [this.major, this.minor, this.micro, this.dev];
  }

  loadJSON(json: number[]) {
    this.major = json[0];
    this.minor = json[1];
    this.micro = json[2];
    this.dev = json[3];

    return this;
  }

  toInt() {
    let f = this.major<<24;

    f |= this.minor<<16;
    f |= this.micro<<8;
    f |= this.dev;

    return f;
  }
}

